-- Triggers
DELIMITER $$
CREATE TRIGGER `tr_bir_or_number_insert` AFTER INSERT ON `bir_or_numbers` FOR EACH ROW BEGIN

    INSERT INTO `bir_audit_trail` (

        `order_id`, `user_id`, `action`, `table_name`, 

        `record_id`, `field_changed`, `old_value`, `new_value`, 

        `reason`, `ip_address`

    ) VALUES (

        NEW.order_id, 

        (SELECT created_by FROM bir_or_series WHERE series_code = NEW.or_series LIMIT 1),

        'create',

        'bir_or_numbers',

        NEW.or_id,

        'or_full_number',

        NULL,

        NEW.or_full_number,

        'OR number issued',

        NULL

    );

END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER `tr_bir_or_number_update` AFTER UPDATE ON `bir_or_numbers` FOR EACH ROW BEGIN

    IF NEW.status != OLD.status AND NEW.status IN ('void', 'cancelled') THEN

        INSERT INTO `bir_audit_trail` (

            `order_id`, `user_id`, `action`, `table_name`, 

            `record_id`, `field_changed`, `old_value`, `new_value`, 

            `reason`, `ip_address`

        ) VALUES (

            NEW.order_id,

            NEW.voided_by,

            NEW.status,

            'bir_or_numbers',

            NEW.or_id,

            'status',

            OLD.status,

            NEW.status,

            NEW.void_reason,

            NULL

        );

    END IF;

END$$
DELIMITER ;

